import { useState } from 'react'
import { Building2, Plus, Users, FolderKanban, ChevronRight, X } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { useWorkspaceStore } from '@/app/store/workspaceStore'
import { useTenant } from '@/app/providers/TenantProvider'
import { useIdentity } from '@/app/providers/IdentityProvider'
import { workplacesService } from '@/integrations/supabase/workplaces'
import { useDefaultWorkplace } from './useDefaultWorkplace'
import type { Workplace } from '@/entities/workspace/types'

export function WorkplacesPage() {
  const navigate = useNavigate()
  const setWorkplaceId = useWorkspaceStore((s) => s.setWorkplaceId)
  const { manifest } = useTenant()
  const { centralUser } = useIdentity()
  const qc = useQueryClient()
  const [showCreate, setShowCreate] = useState(false)
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')

  const { data: workplaces = [], isLoading } = useDefaultWorkplace()

  const createMut = useMutation({
    mutationFn: () =>
      workplacesService.createWorkplace({
        tenantId: manifest?.tenantId ?? '',
        name,
        description: description || undefined,
        createdBy: centralUser?.id ?? '',
      }),
    onSuccess: () => {
      toast.success('Workplace created')
      qc.invalidateQueries({ queryKey: ['workplaces'] })
      setShowCreate(false)
      setName('')
      setDescription('')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const onPick = (wp: Workplace) => {
    setWorkplaceId(wp.id)
    navigate('/app/projects')
  }

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="font-semibold">Workplaces</h2>
            <p className="text-sm text-muted-foreground">Switch between workplaces or create a new one</p>
          </div>
          <button onClick={() => setShowCreate(true)} className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90">
            <Plus size={14} /> New workplace
          </button>
        </div>
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : workplaces.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground mb-3">No workplaces yet</p>
            <button onClick={() => setShowCreate(true)} className="inline-flex items-center gap-1.5 text-sm text-accent hover:underline">
              <Plus size={14} /> Create first workplace
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {workplaces.map((wp) => (
              <button key={wp.id} onClick={() => onPick(wp)} className="text-left bg-surface rounded-xl border border-border p-5 hover:border-accent/50 transition-colors">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-lg bg-accent/10 text-accent flex items-center justify-center">
                      <Building2 size={16} />
                    </div>
                    <div>
                      <p className="font-medium text-sm">{wp.name}</p>
                      {wp.description && <p className="text-xs text-muted-foreground mt-0.5">{wp.description}</p>}
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-muted-foreground" />
                </div>
                <div className="flex items-center gap-4 mt-4 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1"><Users size={12} /> {wp.memberCount ?? 0} members</span>
                  <span className="flex items-center gap-1"><FolderKanban size={12} /> {wp.projectCount ?? 0} projects</span>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>

      {showCreate && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-surface rounded-2xl border border-border w-full max-w-md shadow-xl">
            <div className="flex items-center justify-between p-5 border-b border-border">
              <h3 className="font-semibold">New workplace</h3>
              <button onClick={() => setShowCreate(false)} className="p-1.5 rounded-lg hover:bg-muted"><X size={16} /></button>
            </div>
            <div className="p-5 flex flex-col gap-4">
              <div>
                <label className="text-sm font-medium block mb-1.5">Name *</label>
                <input value={name} onChange={(e) => setName(e.target.value)} autoFocus className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
              </div>
              <div>
                <label className="text-sm font-medium block mb-1.5">Description</label>
                <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent resize-none" />
              </div>
              <div className="flex justify-end gap-2">
                <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground">Cancel</button>
                <button onClick={() => createMut.mutate()} disabled={!name || createMut.isPending} className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90 disabled:opacity-50">
                  {createMut.isPending ? 'Creating…' : 'Create'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
